-- Expands all five Sandwiches sub-tabs (Breakfast Sandwiches, Specialty Sandwiches,
-- Wraps & Bowls, Sides & Bites, Snacking) to 100+ items each. All item names are
-- original to this shop.
USE pos_system;

SET @dept_sandwiches = (SELECT id FROM categories WHERE name = 'Sandwiches' AND parent_id IS NULL);
SET @sub_breakfast = (SELECT id FROM categories WHERE name = 'Breakfast Sandwiches' AND parent_id = @dept_sandwiches);
SET @sub_specialty = (SELECT id FROM categories WHERE name = 'Specialty Sandwiches' AND parent_id = @dept_sandwiches);
SET @sub_wraps = (SELECT id FROM categories WHERE name = 'Wraps & Bowls' AND parent_id = @dept_sandwiches);
SET @sub_sides = (SELECT id FROM categories WHERE name = 'Sides & Bites' AND parent_id = @dept_sandwiches);
SET @sub_snacking = (SELECT id FROM categories WHERE name = 'Snacking' AND parent_id = @dept_sandwiches);

-- ---- Breakfast Sandwiches (+92) ----

-- ---- Specialty Sandwiches (+86) ----

-- ---- Wraps & Bowls (+90) ----

